            Describe.Lean(DescribeId.Create("realinfimumprimeboundary-finite-boundary-sums"),
                DeclarationHandle.Create(Prefix + "finite_boundary_sums"),
                H("Finite head and tail at any positive price"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Let C=cutoff(lambda)=1+lambda^-1>1 and A={p in S:p^2<=C}. For every prime p>1, log p>0. The logarithm comparison log(p^2)<=log C is equivalent to critical>=1; it yields b=critical in A, including equality. Its clock increment is log C-2 log p and its probability is C^-1 by the real-power exponential definition. In the complement b=1, its clock increment is zero and its probability is p^-2. Splitting the two finite sums proves Delta=card(A)*log C-2*theta(A) and U=card(A)*[-log(1-C^-1)]+sum_(S\\A)[-log(1-p^-2)]. At p^2=C both probability expressions coincide and the clock increment vanishes."))),
