                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For S=Nat.primesLE P and y=sqrt C, put x=min(P,y). A membership proof using Nat.le_floor_iff and Real.le_sqrt identifies A with Nat.primesLE floor(x). Its card is primeCounting floor(x), and its log sum is the literal Chebyshev theta x. The complementary set is exactly the prime-filtered natural Ioc floor(x) P. Therefore Delta=pi(x)*log C-2*theta(x) and U=pi(x)*[-log(1-C^-1)]+sum_(x<p<=P)[-log(1-p^-2)]. The formulas cover y>P, an empty head, prime lower ties, and the included upper endpoint."))),
                DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("realinfimumprimeboundary-boundary-dual-identity"),
